alter table public.spec_definitions enable trigger spec_rows_definition_guard;
alter table public.spec_templates enable trigger spec_coherence_publication_guard;
do $revalidate$ declare r record; begin
 for r in select d.validation_rules->'rows_schema' as schema from public.spec_definitions d join chilean_language_affected_row_definitions a on a.definition_id=d.id loop
  perform public.spec_rows_schema_validate_internal_v1(r.schema);
 end loop;
 for r in select d.validation_rules->'rows_schema' as schema,f.value_json as value from public.spec_facts f join public.spec_definitions d on d.id=f.spec_definition_id join chilean_language_affected_row_definitions a on a.definition_id=d.id where f.value_json is not null loop
  perform public.spec_rows_validate_internal_v1(r.schema,r.value);
 end loop;
 for r in select d.validation_rules->'rows_schema' as schema,p.value_json as value from public.product_spec_values p join public.spec_definitions d on d.id=p.spec_definition_id join chilean_language_affected_row_definitions a on a.definition_id=d.id where p.value_json is not null loop
  perform public.spec_rows_validate_internal_v1(r.schema,r.value);
 end loop;
 for r in select t.id,t.form_contract from public.spec_templates t where t.tenant_id is null and t.is_active loop
  perform public.spec_coherence_metadata_internal_v1(r.form_contract,public.spec_coherence_fields_internal_v1(r.id));
 end loop;
end $revalidate$;
