update public.spec_templates set form_contract=jsonb_set(form_contract,'{helpers}',coalesce(form_contract->'helpers','{}'::jsonb)||'{"assembly_frame_fitment_claims": "Una holgura o un OLD admitido conserva rueda, montaje, tapabarros y fuente. El ancho propio del cuadro no es el conjunto de anchos de maza permitidos. Una declaración condicionada necesita sus condiciones.", "assembly_wheel_members": "Cada rueda conserva medidas y montajes propios. Compartir diámetro no aprueba neumático ni cassette. La posición delantera no prohíbe por sí sola una transmisión documentada; declarar el puerto que existe."}'::jsonb),updated_at=now() where tenant_id is null and is_active and key='bicycle' and form_contract->'helpers' is distinct from (coalesce(form_contract->'helpers','{}'::jsonb)||'{"assembly_frame_fitment_claims": "Una holgura o un OLD admitido conserva rueda, montaje, tapabarros y fuente. El ancho propio del cuadro no es el conjunto de anchos de maza permitidos. Una declaración condicionada necesita sus condiciones.", "assembly_wheel_members": "Cada rueda conserva medidas y montajes propios. Compartir diámetro no aprueba neumático ni cassette. La posición delantera no prohíbe por sí sola una transmisión documentada; declarar el puerto que existe."}'::jsonb);
update public.spec_templates set form_contract=jsonb_set(form_contract,'{helpers}',coalesce(form_contract->'helpers','{}'::jsonb)||'{"brake_actuation": "Cómo acciona esta manilla. Una manilla de cable que mueve un convertidor sigue siendo mecánica.", "brake_bleed_ports": "Sólo puertos que el procedimiento OEM identifica para purgar esta manilla. No convierte un tornillo de sellado en purgador.", "brake_piece_hydraulic_ports": "Salidas hidráulicas de la manilla principal. La auxiliar en línea tiene su propia tabla de conexiones.", "handlebar_clamp_mm": "Diámetro exterior de la sección donde se fija esta manilla. No se restringe a 22,2 o 23,8 ni se deduce del tiro.", "lever_cable_head_profiles": "Describe el alojamiento de esta manilla. Doble cabeza describe un cable sin cortar, no un alojamiento universal.", "lever_cable_interface": "Una manilla en línea puede actuar sobre la funda con el cable pasante. Ambos usos requieren documentación del mismo modelo.", "lever_cable_pull": "El tiro que ESTA manilla entrega. Lo que un cáliper exige es otra celda en otra pieza, y una no implica la otra.", "lever_hydraulic_role": "La manilla auxiliar en línea conecta con un mando principal y con el resto del circuito. No es un par de manillas."}'::jsonb),updated_at=now() where tenant_id is null and is_active and key='brake_lever' and form_contract->'helpers' is distinct from (coalesce(form_contract->'helpers','{}'::jsonb)||'{"brake_actuation": "Cómo acciona esta manilla. Una manilla de cable que mueve un convertidor sigue siendo mecánica.", "brake_bleed_ports": "Sólo puertos que el procedimiento OEM identifica para purgar esta manilla. No convierte un tornillo de sellado en purgador.", "brake_piece_hydraulic_ports": "Salidas hidráulicas de la manilla principal. La auxiliar en línea tiene su propia tabla de conexiones.", "handlebar_clamp_mm": "Diámetro exterior de la sección donde se fija esta manilla. No se restringe a 22,2 o 23,8 ni se deduce del tiro.", "lever_cable_head_profiles": "Describe el alojamiento de esta manilla. Doble cabeza describe un cable sin cortar, no un alojamiento universal.", "lever_cable_interface": "Una manilla en línea puede actuar sobre la funda con el cable pasante. Ambos usos requieren documentación del mismo modelo.", "lever_cable_pull": "El tiro que ESTA manilla entrega. Lo que un cáliper exige es otra celda en otra pieza, y una no implica la otra.", "lever_hydraulic_role": "La manilla auxiliar en línea conecta con un mando principal y con el resto del circuito. No es un par de manillas."}'::jsonb);
update public.spec_templates set form_contract=jsonb_set(form_contract,'{helpers}',coalesce(form_contract->'helpers','{}'::jsonb)||'{"combined_control_brake_configurations": "Una configuración completa por fila. El líquido, el tiro y el conector se declaran junto al accionamiento al que pertenecen, así que una manilla de cable no puede llevar un fluido y una hidráulica no puede llevar un tiro. Dos líquidos aprobados son dos filas completas, cada una con su sistema y su fuente: compartir clase de fluido no es una aprobación, y lo aprobado para un mando no vale para el otro por venir en la misma caja. El conector y su especificación describen el extremo externo, así que sólo se declaran donde se declaró que ese extremo existe. Si el cable termina en un conversor hidráulico externo, el mando sigue siendo de cable. El líquido y el conector hidráulico pertenecen al conversor o cáliper y se documentan en la ficha de esa pieza."}'::jsonb),updated_at=now() where tenant_id is null and is_active and key='brake_shift_combined_control' and form_contract->'helpers' is distinct from (coalesce(form_contract->'helpers','{}'::jsonb)||'{"combined_control_brake_configurations": "Una configuración completa por fila. El líquido, el tiro y el conector se declaran junto al accionamiento al que pertenecen, así que una manilla de cable no puede llevar un fluido y una hidráulica no puede llevar un tiro. Dos líquidos aprobados son dos filas completas, cada una con su sistema y su fuente: compartir clase de fluido no es una aprobación, y lo aprobado para un mando no vale para el otro por venir en la misma caja. El conector y su especificación describen el extremo externo, así que sólo se declaran donde se declaró que ese extremo existe. Si el cable termina en un conversor hidráulico externo, el mando sigue siendo de cable. El líquido y el conector hidráulico pertenecen al conversor o cáliper y se documentan en la ficha de esa pieza."}'::jsonb);
update public.spec_templates set form_contract=jsonb_set(form_contract,'{helpers}',coalesce(form_contract->'helpers','{}'::jsonb)||'{"bolt_pattern": "Sujeción publicada, por ejemplo un perno M8. Dos patas de cambio distintas pueden compartir perno sin compartir código ni calce: el perno no identifica la pieza.", "hanger_frame_interface": "Cómo se une esta pieza al cuadro. UDH es una postiza física sobre una unión estandarizada; un cambio Full Mount sustituye la postiza y por eso no es una opción de esta ficha."}'::jsonb),updated_at=now() where tenant_id is null and is_active and key='derailleur_hanger' and form_contract->'helpers' is distinct from (coalesce(form_contract->'helpers','{}'::jsonb)||'{"bolt_pattern": "Sujeción publicada, por ejemplo un perno M8. Dos patas de cambio distintas pueden compartir perno sin compartir código ni calce: el perno no identifica la pieza.", "hanger_frame_interface": "Cómo se une esta pieza al cuadro. UDH es una postiza física sobre una unión estandarizada; un cambio Full Mount sustituye la postiza y por eso no es una opción de esta ficha."}'::jsonb);
