update public.spec_templates set form_contract=jsonb_set(form_contract,'{helpers}',coalesce(form_contract->'helpers','{}'::jsonb)||'{"brake_circuits": "Un circuito por freno accionado: qué manilla mueve qué cáliper o mecanismo y por qué línea, apuntando a las filas de piezas. El líquido con que se entrega es del circuito; el que cada pieza admite es de esa pieza. Declararlo no verifica que las piezas calcen.", "kit_members": "Una fila por pieza física incluida, con su perfil propio: cada manilla, cada cáliper, cada línea, rotor, adaptador o pastilla. Dos piezas del mismo modelo son dos filas. Las medidas y conexiones viven en el perfil de cada pieza, nunca en esta raíz."}'::jsonb),updated_at=now() where tenant_id is null and is_active and key='hydraulic_disc_brake' and form_contract->'helpers' is distinct from (coalesce(form_contract->'helpers','{}'::jsonb)||'{"brake_circuits": "Un circuito por freno accionado: qué manilla mueve qué cáliper o mecanismo y por qué línea, apuntando a las filas de piezas. El líquido con que se entrega es del circuito; el que cada pieza admite es de esa pieza. Declararlo no verifica que las piezas calcen.", "kit_members": "Una fila por pieza física incluida, con su perfil propio: cada manilla, cada cáliper, cada línea, rotor, adaptador o pastilla. Dos piezas del mismo modelo son dos filas. Las medidas y conexiones viven en el perfil de cada pieza, nunca en esta raíz."}'::jsonb);
