update public.spec_templates set form_contract=jsonb_set(form_contract,'{helpers}',coalesce(form_contract->'helpers','{}'::jsonb)||'{"assembly_wheel_members": "Cada rueda conserva medidas y montajes propios. Compartir diámetro no aprueba neumático ni cassette. La posición delantera no prohíbe por sí sola una transmisión documentada; declarar el puerto que existe.", "wheel_compatible_claims": "Lo que el fabricante declara que esta rueda acepta. No es lo que viene en la caja, que va en los miembros del conjunto, y ninguna de las dos cosas implica la otra: una rueda puede venir con un neumático que no es el único que acepta, y aceptar uno que no incluye. Un diámetro igual no es una declaración de compatibilidad."}'::jsonb),updated_at=now() where tenant_id is null and is_active and key='wheel' and form_contract->'helpers' is distinct from (coalesce(form_contract->'helpers','{}'::jsonb)||'{"assembly_wheel_members": "Cada rueda conserva medidas y montajes propios. Compartir diámetro no aprueba neumático ni cassette. La posición delantera no prohíbe por sí sola una transmisión documentada; declarar el puerto que existe.", "wheel_compatible_claims": "Lo que el fabricante declara que esta rueda acepta. No es lo que viene en la caja, que va en los miembros del conjunto, y ninguna de las dos cosas implica la otra: una rueda puede venir con un neumático que no es el único que acepta, y aceptar uno que no incluye. Un diámetro igual no es una declaración de compatibilidad."}'::jsonb);
